    <div style="margin-bottom:16px;"><div style="font-size:13px;font-weight:600;color:#2a2420;margin-bottom:6px;">Disadvantages</div><div style="font-size:15px;font-style:italic;color:#3a3028;line-height:1.8;margin:8px 0 0;padding:10px 16px;background:rgba(196,168,130,0.05);border-radius:8px;">slower progress</div><div style="font-size:15px;font-style:italic;color:#3a3028;line-height:1.8;margin:8px 0 0;padding:10px 16px;background:rgba(196,168,130,0.05);border-radius:8px;">high dual workload</div><div style="font-size:15px;font-style:italic;color:#3a3028;line-height:1.8;margin:8px 0 0;padding:10px 16px;background:rgba(196,168,130,0.05);border-radius:8px;">risk of continuing to procrastinate</div></div>
